-- Verify the typmod of interval, timestamp and time, and make_interval, which
-- ty does (ty/DESIGN.md sections 18 and 19).
-- (Errors are server.sh's: a run stops at its first.)
SELECT v, v::interval(0) AS p0, v::interval(1) AS p1, v::interval(3) AS p3, v::interval(6) AS p6, v::interval second(2) AS s2, v::interval minute to second(1) AS ms1 FROM (VALUES ('1 day 2 hours 3 minutes 4.5678 seconds'::interval), ('-1 day -2 hours -3 minutes -4.5678 seconds'), ('0.0000005 seconds'), ('-0.0000005 seconds'), ('1.5 seconds'), ('-1.5 seconds'), ('2.5 seconds'), ('infinity'), ('0')) x(v);
SELECT v, v::interval year AS y, v::interval month AS m, v::interval year to month AS ym, v::interval day AS d, v::interval hour AS h, v::interval minute AS mi, v::interval day to hour AS dh, v::interval day to minute AS dm, v::interval day to second AS ds, v::interval hour to minute AS hm, v::interval hour to second AS hs FROM (VALUES ('1 year 14 months 3 days 2 hours 3 minutes 4.5 seconds'::interval), ('-1 year -2 months -3 days -2 hours -3 minutes -4.5 seconds'), ('1 month 40 days 100:30:30'), ('0'), ('-infinity')) x(v);
SELECT t, t::timestamp(0) AS p0, t::timestamp(1) AS p1, t::timestamp(3) AS p3, t::timestamp(6) AS p6, t::timestamp AS pd FROM (VALUES ('2024-02-29 13:45:56.789012'::timestamp), ('2024-02-29 13:45:56.5'), ('2024-02-29 13:45:56.4999999'), ('0001-01-01 00:00:00.5 BC'), ('infinity'), ('-infinity'), ('1999-12-31 23:59:59.9999995')) x(t);
SELECT t, t::time(0) AS p0, t::time(2) AS p2, t::time(6) AS p6, t::time AS pd FROM (VALUES ('13:45:56.789012'::time), ('13:45:56.5'), ('23:59:59.9999995'), ('00:00:00.0000004'), ('24:00:00')) x(t);
SELECT z, z::timestamptz(0) AS p0, z::timestamptz(2) AS p2 FROM (VALUES ('2024-02-29 13:45:56.789012+00'::timestamptz), ('2024-02-29 23:59:59.999+00'), ('infinity')) x(z);
SELECT make_interval(0, 0, 0, 0, 0, 0, 0) AS a, make_interval(1, 2, 3, 4, 5, 6, 7.5) AS b, make_interval(1, 0, 0, 0, 0, 0, 0) AS c, make_interval(0, 0, 2, 1, 0, 0, 0) AS d, make_interval(0, 0, 0, 0, 25, 61, 61.5) AS e, make_interval(0, 0, 0, 0, 0, 0, 0.0000005) AS f, make_interval(-1, 13, 0, 0, 0, 0, 0) AS g, make_interval(0, 0, 0, 0, 0, 0, -1.25) AS h;
SELECT i, i::interval(2) AS p2 FROM (SELECT (n || ' hours')::interval + '0.126 seconds'::interval AS i FROM generate_series(1, 5) n) x;
